import type {
  ProviderBCommitBatch,
  ProviderBReservationRow,
  ProviderBStorage,
  ProviderBStockRow,
  Reservation,
  Service,
  Stock,
} from "./types";
import { createReservationWorkflow } from "./reservation";
import { decodeDecimalText, isId, isQuantity, isRecord, isRevision, isUnits } from "./validation";

function readEnvelopeValue(raw: unknown): { kind: "found"; value: unknown } | { kind: "missing" } {
  if (!isRecord(raw) || typeof raw.ok !== "boolean") throw new Error("storage_unavailable");
  if (raw.ok) return { kind: "found", value: raw.value };
  if (!isRecord(raw.error)) throw new Error("storage_unavailable");
  if (raw.error.reason === "NO_SUCH_KEY") return { kind: "missing" };
  throw new Error("storage_unavailable");
}

function decodeStockRow(value: unknown, requestedSku: string): Stock | undefined {
  if (!isRecord(value) || !isId(value.itemKey) || value.itemKey !== requestedSku) return undefined;
  const totalUnits = decodeDecimalText(value.onHandText);
  const reservedUnits = decodeDecimalText(value.heldText);
  const revision = decodeDecimalText(value.revisionText);
  if (totalUnits === undefined || reservedUnits === undefined || revision === undefined ||
      !isUnits(totalUnits) || !isUnits(reservedUnits) || reservedUnits > totalUnits ||
      !isRevision(revision)) return undefined;
  return { sku: value.itemKey, totalUnits, reservedUnits, revision };
}

function decodeReservationRow(value: unknown, requestedReservationId: string): Reservation | undefined {
  if (!isRecord(value) || !isId(value.bookingKey) || value.bookingKey !== requestedReservationId ||
      !isId(value.itemKey)) return undefined;
  const quantity = decodeDecimalText(value.unitsText);
  if (quantity === undefined || !isQuantity(quantity)) return undefined;
  return { reservationId: value.bookingKey, sku: value.itemKey, quantity };
}

function stockRowFrom(stock: Stock): ProviderBStockRow {
  return {
    itemKey: stock.sku,
    onHandText: String(stock.totalUnits),
    heldText: String(stock.reservedUnits),
    revisionText: String(stock.revision),
  };
}

function reservationRowFrom(reservation: Reservation): ProviderBReservationRow {
  return {
    bookingKey: reservation.reservationId,
    itemKey: reservation.sku,
    unitsText: String(reservation.quantity),
  };
}

function commitBatchFrom(stock: Stock, reservation: Reservation): ProviderBCommitBatch {
  const nextStock = {
    ...stock,
    reservedUnits: stock.reservedUnits + reservation.quantity,
    revision: stock.revision + 1,
  };
  const reservationRow = reservationRowFrom(reservation);
  return {
    expectedRevisionText: String(stock.revision),
    stockRow: stockRowFrom(nextStock),
    reservationRow,
    outboxRows: [{
      key: "reservation.created:" + reservation.reservationId,
      category: "reservation",
      name: "created",
      payload: {
        bookingKey: reservationRow.bookingKey,
        itemKey: reservationRow.itemKey,
        unitsText: reservationRow.unitsText,
      },
    }],
  };
}

export function createProviderBReservationService({ storage }: { storage: ProviderBStorage }): Service {
  return createReservationWorkflow({
    async readStock(sku) {
      const envelope = readEnvelopeValue(await storage.read({ collection: "inventory", key: sku }));
      if (envelope.kind === "missing") return undefined;
      const stock = decodeStockRow(envelope.value, sku);
      if (stock === undefined) throw new Error("storage_unavailable");
      return stock;
    },
    async readReservation(reservationId) {
      const envelope = readEnvelopeValue(await storage.read({ collection: "reservations", key: reservationId }));
      if (envelope.kind === "missing") return undefined;
      const reservation = decodeReservationRow(envelope.value, reservationId);
      if (reservation === undefined) throw new Error("storage_unavailable");
      return reservation;
    },
    async commitReservation(stock, reservation) {
      const nextRevision = stock.revision + 1;
      if (!isRevision(nextRevision)) throw new Error("storage_unavailable");
      const outcome = await storage.commitBatch(commitBatchFrom(stock, reservation));
      if (outcome === "revision_conflict") return "revision_conflict";
      if (outcome !== "applied") throw new Error("storage_unavailable");
      return "committed";
    },
  });
}

